import{_ as a,o as i,c as t,a2 as p}from"./chunks/framework.CHeM0PsO.js";const c=JSON.parse('{"title":"Экспорт и импорт","description":"","frontmatter":{},"headers":[],"relativePath":"ru/advanced/export-import.md","filePath":"ru/advanced/export-import.md","lastUpdated":1784904021000}'),e={name:"ru/advanced/export-import.md"};function h(n,s,l,k,d,r){return i(),t("div",null,[...s[0]||(s[0]=[p(`<h1 id="экспорт-и-импорт" tabindex="-1">Экспорт и импорт <a class="header-anchor" href="#экспорт-и-импорт" aria-label="Permalink to &quot;Экспорт и импорт&quot;">​</a></h1><h2 id="обзор" tabindex="-1">Обзор <a class="header-anchor" href="#обзор" aria-label="Permalink to &quot;Обзор&quot;">​</a></h2><p>swag2mcp поддерживает полный цикл рабочей области через ZIP-архивы. Вы можете экспортировать всю рабочую область (конфиг, файлы спецификаций, скрипты аутентификации) в ZIP-файл и восстановить её на другой машине.</p><h2 id="экспорт" tabindex="-1">Экспорт <a class="header-anchor" href="#экспорт" aria-label="Permalink to &quot;Экспорт&quot;">​</a></h2><p>Создаёт портативную ZIP-резервную копию вашей рабочей области.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Экспорт в файл по умолчанию (swag2mcp-backup-&amp;lt;timestamp&amp;gt;.zip)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Экспорт с пользовательским путём</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/backups/swag2mcp-backup.zip</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Экспорт только определённых спецификаций</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --spec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> meteo</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --spec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> meteo,store</span></span></code></pre></div><h3 id="что-входит-в-экспорт" tabindex="-1">Что входит в экспорт <a class="header-anchor" href="#что-входит-в-экспорт" aria-label="Permalink to &quot;Что входит в экспорт&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Элемент</th><th>Описание</th></tr></thead><tbody><tr><td><code>swag2mcp.yaml</code></td><td>Конфигурационный файл</td></tr><tr><td><code>specs/</code></td><td>Все файлы спецификаций (OpenAPI/Swagger/Postman)</td></tr><tr><td><code>auth_scripts/</code></td><td>Скрипты аутентификации</td></tr><tr><td><code>swag2mcp.meta</code></td><td>Метаданные (информация о версии для совместимости)</td></tr></tbody></table><p>Кэш и ответы <strong>не</strong> экспортируются — они временны и будут устаревшими при восстановлении.</p><h3 id="имя-фаила-по-умолчанию" tabindex="-1">Имя файла по умолчанию <a class="header-anchor" href="#имя-фаила-по-умолчанию" aria-label="Permalink to &quot;Имя файла по умолчанию&quot;">​</a></h3><p>Если вы не указали путь вывода, файл сохраняется как <code>swag2mcp-backup-&lt;YYYY-MM-DD-HHMMSS&gt;.zip</code> в текущей директории (UTC-метка времени).</p><h2 id="импорт" tabindex="-1">Импорт <a class="header-anchor" href="#импорт" aria-label="Permalink to &quot;Импорт&quot;">​</a></h2><p>Восстановление рабочей области из ZIP-резервной копии или импорт файлов спецификаций.</p><h3 id="восстановление-из-zip" tabindex="-1">Восстановление из ZIP <a class="header-anchor" href="#восстановление-из-zip" aria-label="Permalink to &quot;Восстановление из ZIP&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Восстановление полной рабочей области</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> import</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --from-zip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/backup.zip</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Восстановление с перезаписью</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> import</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --from-zip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/backup.zip</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span></span></code></pre></div><p>ZIP должен быть создан командой <code>swag2mcp export</code> — произвольные ZIP-файлы не будут работать.</p><h3 id="импорт-одного-фаила-спецификации" tabindex="-1">Импорт одного файла спецификации <a class="header-anchor" href="#импорт-одного-фаила-спецификации" aria-label="Permalink to &quot;Импорт одного файла спецификации&quot;">​</a></h3><p>Скачайте файл спецификации и добавьте его в рабочую область:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> import</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://example.com/spec.yaml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> myspec</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> import</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/workspace</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://example.com/spec.yaml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> myspec</span></span></code></pre></div><h3 id="пакетныи-импорт-из-существующего-конфига" tabindex="-1">Пакетный импорт из существующего конфига <a class="header-anchor" href="#пакетныи-импорт-из-существующего-конфига" aria-label="Permalink to &quot;Пакетный импорт из существующего конфига&quot;">​</a></h3><p>Скачайте все файлы спецификаций коллекций для указанных спецификаций (доменов):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> import</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --spec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> meteo</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> import</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/workspace</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --spec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> meteo,store</span></span></code></pre></div><p>Это скачивает файл спецификации каждой коллекции, сохраняет его в <code>specs/</code> и обновляет конфиг, чтобы указывать на локальную копию.</p><h2 id="варианты-использования" tabindex="-1">Варианты использования <a class="header-anchor" href="#варианты-использования" aria-label="Permalink to &quot;Варианты использования&quot;">​</a></h2><h3 id="резервное-копирование" tabindex="-1">Резервное копирование <a class="header-anchor" href="#резервное-копирование" aria-label="Permalink to &quot;Резервное копирование&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> swag2mcp-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">date</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +%Y-%m-%d</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.zip</span></span></code></pre></div><h3 id="перенос-на-другую-машину" tabindex="-1">Перенос на другую машину <a class="header-anchor" href="#перенос-на-другую-машину" aria-label="Permalink to &quot;Перенос на другую машину&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># На старой машине</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> swag2mcp.zip</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Скопируйте ZIP на новую машину, затем:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> import</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --from-zip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> swag2mcp.zip</span></span></code></pre></div><h3 id="обмен-конфигурациеи" tabindex="-1">Обмен конфигурацией <a class="header-anchor" href="#обмен-конфигурациеи" aria-label="Permalink to &quot;Обмен конфигурацией&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> template.zip</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Поделитесь template.zip с коллегой</span></span></code></pre></div><h2 id="проверка-после-экспорта" tabindex="-1">Проверка после экспорта <a class="header-anchor" href="#проверка-после-экспорта" aria-label="Permalink to &quot;Проверка после экспорта&quot;">​</a></h2><p>Всегда проверяйте, что ZIP-файл был создан:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ls</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -la</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> swag2mcp-backup-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.zip</span></span></code></pre></div><h2 id="важные-замечания" tabindex="-1">Важные замечания <a class="header-anchor" href="#важные-замечания" aria-label="Permalink to &quot;Важные замечания&quot;">​</a></h2><ul><li><strong>Вывод должен быть путём к файлу, оканчивающимся на <code>.zip</code></strong> — не передавайте директорию</li><li><strong>Кэш и ответы исключены</strong> — сохраняются только конфиг, спецификации и скрипты аутентификации</li><li><strong>ZIP самодостаточен</strong> — его можно восстановить на любой машине с установленным swag2mcp</li><li><strong>Фильтр спецификаций</strong> — используйте <code>--spec</code> для экспорта или импорта только определённых спецификаций</li></ul>`,35)])])}const F=a(e,[["render",h]]);export{c as __pageData,F as default};
